hooks.command:
python -c "
import sys, json, re
data = json.load(sys.stdin)
cmd = data.get('tool_input', {}).get('command', '')
if re.search(r'docker compose up\b.*--build', cmd):
    new_cmd = re.sub(r'docker compose up\s+--build(\s+-d)?(\s+2>&1)?', r'docker compose build && docker compose up -d\2', cmd)
    out = {'hookSpecificOutput': {'hookEventName': 'PreToolUse', 'updatedInput': {'command': new_cmd}, 'additionalContext': 'Rewrote --build to sequential build+up to prevent parallel RAM spike'}}
else:
    out = {'hookSpecificOutput': {'hookEventName': 'PreToolUse'}}
print(json.dumps(out))
"
